Build a small HTTP service for personal notes.

## Requirements
- `POST /notes` with JSON {title, body} creates a note and returns 201 and the note with an id; an empty title returns 400.
- `GET /notes` lists notes; `GET /notes/:id` returns one note or 404.
- `GET /health` returns 200 {"status":"ok"}.
- Node.js (>=24) with TypeScript run directly by node (type stripping), **no npm dependencies**; tests use `node:test` and run with `npm test` (script: `node --test tests/`).
- Deployment: a `Dockerfile` (node:24-alpine) and `docker-compose.yml` exposing the service on host port 8080; a smoke script `scripts/smoke.ts` (run by `npm run smoke`) that exercises /health and creating then fetching a note against http://localhost:8080 and exits non-zero on any failure.

## Non-functional requirements
- Every endpoint responds in under 50 ms on a local machine (p95) for up to 1,000 stored notes.
- State is in memory; restarting the service clears notes (documented).
- The service logs one line per request and never logs request bodies.
import { createServer, type IncomingMessage, type Server, type ServerResponse } from "node:http";
import { NoteStore } from "./store.ts";
import { parseNoteInput } from "./validation.ts";

const MAX_BODY = 1024 * 1024; // 1 MiB

function send(res: ServerResponse, status: number, payload: unknown): void {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(JSON.stringify(payload));
}

function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on("data", (c: Buffer) => {
      if (tooLarge) return; // keep draining so the 400 response can be delivered
      size += c.length;
      if (size > MAX_BODY) {
        tooLarge = true;
        chunks.length = 0;
        resolve(null);
        return;
      }
      chunks.push(c);
    });
    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    req.on("error", () => resolve(null));
  });
}

type Ctx = { req: IncomingMessage; res: ServerResponse; store: NoteStore; method: string };

const notFound = (res: ServerResponse) => send(res, 404, { error: "not found" });
const notAllowed = (res: ServerResponse) => send(res, 405, { error: "method not allowed" });

