import { NoteStore } from "./store.ts";
import { parseNoteInput } from "./validation.ts";

const MAX_BODY = 1024 * 1024; // 1 MiB

function send(res: ServerResponse, status: number, payload: unknown): void {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(JSON.stringify(payload));
}

function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on("data", (c: Buffer) => {
      if (tooLarge) return; // keep draining so the 400 response can be delivered
      size += c.length;
      if (size > MAX_BODY) {
        tooLarge = true;
        chunks.length = 0;
        resolve(null);
        return;
      }
      chunks.push(c);
    });
    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    req.on("error", () => resolve(null));
  });
}

type Ctx = { req: IncomingMessage; res: ServerResponse; store: NoteStore; method: string };

const notFound = (res: ServerResponse) => send(res, 404, { error: "not found" });
const notAllowed = (res: ServerResponse) => send(res, 405, { error: "method not allowed" });

function handleHealth({ res, method }: Ctx): void {
  if (method !== "GET") return notAllowed(res);
  send(res, 200, { status: "ok" });
}

async function handleNotes({ req, res, store, method }: Ctx): Promise<void> {
  if (method === "GET") return send(res, 200, store.list());
  if (method !== "POST") return notAllowed(res);
  const raw = await readBody(req);
  if (raw === null) return send(res, 400, { error: "request body too large or unreadable" });
  const parsed = parseNoteInput(raw);
  if (!parsed.ok) return send(res, 400, { error: parsed.error });
  send(res, 201, store.create(parsed.title, parsed.body));
}

function handleNoteById({ res, store, method }: Ctx, rawId: string): void {
  if (method !== "GET") return notAllowed(res);
  let id: string;
  try {
    id = decodeURIComponent(rawId);
  } catch {
    return notFound(res);
  }
  const note = store.get(id);
  if (!note) return notFound(res);
  send(res, 200, note);
}

async function route(ctx: Ctx): Promise<void> {
  const path = new URL(ctx.req.url ?? "/", "http://localhost").pathname;
  if (path === "/health") return handleHealth(ctx);
  if (path === "/notes") return handleNotes(ctx);
  const m = /^\/notes\/([^/]+)$/.exec(path);
  if (m) return handleNoteById(ctx, m[1]);
  notFound(ctx.res);
}

export type Logger = (line: string) => void;

export function createApp(store: NoteStore = new NoteStore(), log: Logger = console.log): Server {
  return createServer((req, res) => {
    const start = performance.now();
    const method = req.method ?? "GET";
    // Log path only (no query string, no body); strip control chars to keep one line.
    const path = (req.url ?? "/").split("?")[0].replace(/[\x00-\x1f\x7f]/g, "");
    res.on("finish", () => {
      log(`${method} ${path} ${res.statusCode} ${(performance.now() - start).toFixed(1)}ms`);
    });
    void route({ req, res, store, method });
  });
}
